using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    long long p = 0;
    for (long long i = 2; i <= n / i; ++i) {
        if (n % i == 0) {
            p = i;
            break;
        }
    }

    if (p == 0) {
        cout << n << '\n';
        return 0;
    }

    long long temp = n;
    while (temp % p == 0) {
        temp /= p;
    }

    cout << (temp == 1 ? p : 1) << '\n';
    return 0;
}

